const weightInKg = 70;
const distanceInMeters = 100;
console.log(weightInKg + distanceInMeters); // 170，一個沒有任何意義的數字

function kg(value) { return { unit: 'kg', value }; }
function meter(value) { return { unit: 'm', value }; }

function addSameUnit(a, b) {
  if (a.unit !== b.unit) {
    throw new Error(`無法把 ${a.unit} 跟 ${b.unit} 相加`);
  }
  return { unit: a.unit, value: a.value + b.value };
}

try {
  console.log(addSameUnit(kg(70), meter(100)));
} catch (e) {
  console.log(e.message);
}

